import bcrypt from 'bcrypt';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(express.json());

const SALT_ROUNDS = 10;
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_FAILED_ATTEMPTS = 5;
const SESSION_EXPIRY = 24 * 60 * 60 * 1000; // 24 hours

// In-memory storage (replace with database in production)
const users = new Map();
const sessions = new Map();
const failedAttempts = new Map();

function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function validatePassword(password) {
  if (password.length < 8) return false;
  return /[A-Z]/.test(password) && /[0-9]/.test(password);
}

function isRateLimited(email) {
  const record = failedAttempts.get(email);
  if (!record) return false;

  const now = Date.now();
  if (now - record.firstAttempt > RATE_LIMIT_WINDOW) {
    failedAttempts.delete(email);
    return false;
  }

  return record.count >= MAX_FAILED_ATTEMPTS;
}

function recordFailedAttempt(email) {
  const now = Date.now();
  const record = failedAttempts.get(email);

  if (record && now - record.firstAttempt < RATE_LIMIT_WINDOW) {
    record.count++;
  } else {
    failedAttempts.set(email, { count: 1, firstAttempt: now });
  }
}

function clearFailedAttempts(email) {
  failedAttempts.delete(email);
}

function createSession(email) {
  const sessionId = uuidv4();
  sessions.set(sessionId, {
    email,
    createdAt: Date.now(),
    expiresAt: Date.now() + SESSION_EXPIRY
  });
  return sessionId;
}

function getSession(sessionId) {
  const session = sessions.get(sessionId);
  if (!session) return null;

  if (Date.now() > session.expiresAt) {
    sessions.delete(sessionId);
    return null;
  }

  return session;
}

app.post('/signup', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    if (!validateEmail(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    if (!validatePassword(password)) {
      return res.status(400).json({
        error: 'Password must be at least 8 characters with uppercase and number'
      });
    }

    if (users.has(email)) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);
    users.set(email, { passwordHash, createdAt: new Date() });

    res.status(201).json({ message: 'Signup successful' });
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

app.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    if (isRateLimited(email)) {
      return res.status(429).json({
        error: 'Too many failed attempts. Try again later.'
      });
    }

    const user = users.get(email);
    if (!user) {
      recordFailedAttempt(email);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const passwordMatch = await bcrypt.compare(password, user.passwordHash);
    if (!passwordMatch) {
      recordFailedAttempt(email);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    clearFailedAttempts(email);
    const sessionId = createSession(email);

    res.json({
      message: 'Login successful',
      sessionId,
      expiresIn: SESSION_EXPIRY / 1000
    });
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

app.post('/logout', (req, res) => {
  const { sessionId } = req.body;

  if (!sessionId || !sessions.has(sessionId)) {
    return res.status(400).json({ error: 'Invalid session' });
  }

  sessions.delete(sessionId);
  res.json({ message: 'Logout successful' });
});

app.get('/profile', (req, res) => {
  const sessionId = req.headers.authorization?.split(' ')[1];

  if (!sessionId) {
    return res.status(401).json({ error: 'No session provided' });
  }

  const session = getSession(sessionId);
  if (!session) {
    return res.status(401).json({ error: 'Invalid or expired session' });
  }

  res.json({
    email: session.email,
    expiresAt: new Date(session.expiresAt).toISOString()
  });
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Auth server running on http://localhost:${PORT}`);
});
