import fetch from 'node-fetch';

const BASE_URL = 'http://localhost:3000';

async function signup(email, password) {
  const res = await fetch(`${BASE_URL}/signup`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  return res.json();
}

async function login(email, password) {
  const res = await fetch(`${BASE_URL}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  return res.json();
}

async function logout(sessionId) {
  const res = await fetch(`${BASE_URL}/logout`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId })
  });
  return res.json();
}

async function getProfile(sessionId) {
  const res = await fetch(`${BASE_URL}/profile`, {
    headers: { 'Authorization': `Bearer ${sessionId}` }
  });
  return res.json();
}

// Demo
async function demo() {
  console.log('=== Auth System Demo ===\n');

  // Signup
  console.log('1. Signup');
  let result = await signup('user@example.com', 'Password123');
  console.log(result);

  // Try duplicate signup
  console.log('\n2. Duplicate signup (should fail)');
  result = await signup('user@example.com', 'Password456');
  console.log(result);

  // Login
  console.log('\n3. Login');
  result = await login('user@example.com', 'Password123');
  console.log(result);
  const sessionId = result.sessionId;

  // Get profile
  console.log('\n4. Get profile');
  result = await getProfile(sessionId);
  console.log(result);

  // Failed login attempts
  console.log('\n5. Failed login attempts');
  for (let i = 0; i < 6; i++) {
    result = await login('user@example.com', 'WrongPassword');
    console.log(`Attempt ${i + 1}:`, result.error || result.message);
  }

  // Logout
  console.log('\n6. Logout');
  result = await logout(sessionId);
  console.log(result);

  // Try using expired session
  console.log('\n7. Try profile with expired session');
  result = await getProfile(sessionId);
  console.log(result);
}

demo().catch(console.error);
